<?php
return function (Router $r) {
    $r->get('/small-business',fn()=>View::render(__DIR__.'/views/index.php',['title'=>'Small business','projects'=>Db::all("SELECT p.*,COALESCE(SUM(CASE WHEN e.kind='time' THEN e.quantity ELSE 0 END),0) hours,COALESCE(SUM(CASE WHEN e.kind='income' THEN e.quantity ELSE 0 END),0) income,COALESCE(SUM(CASE WHEN e.kind='cost' THEN e.quantity ELSE 0 END),0) cost FROM business_projects p LEFT JOIN business_entries e ON e.project_id=p.id GROUP BY p.id ORDER BY p.status,p.id DESC")]));
    $r->post('/small-business/project',function () { Db::run('INSERT INTO business_projects(name,client,hourly_rate,notes) VALUES (?,?,?,?)',[text_input('name'),text_input('client',200,false),cents($_POST['hourly_rate'] ?? '0',true)/100,text_input('notes',2000,false)]); return redirect('/small-business','Project created.'); });
    $r->post('/small-business/project/{id}/entry',function ($p) { $id=record_id($p['id']); if (!Db::one("SELECT id FROM business_projects WHERE id=? AND status='active'",[$id])) throw new InvalidArgumentException('Choose an active project.'); $kind=text_input('kind',20); if (!in_array($kind,['time','income','cost'],true)) throw new InvalidArgumentException('Choose an entry type.'); $amount=cents($_POST['quantity'] ?? '')/100; Db::run('INSERT INTO business_entries(project_id,date,kind,quantity,note) VALUES (?,?,?,?,?)',[$id,valid_date(text_input('date')),$kind,$amount,text_input('note',1000,false)]); return redirect('/small-business/project/'.$id,'Entry saved.'); });
    $r->get('/small-business/project/{id}',function ($p) { $id=record_id($p['id']); $project=Db::one('SELECT * FROM business_projects WHERE id=?',[$id]); if (!$project) throw new InvalidArgumentException('Project not found.'); return View::render(__DIR__.'/views/project.php',['title'=>$project['name'],'project'=>$project,'entries'=>Db::all('SELECT * FROM business_entries WHERE project_id=? ORDER BY date DESC,id DESC',[$id])]); });
    $r->post('/small-business/project/{id}/close',function ($p) { Db::run("UPDATE business_projects SET status='closed' WHERE id=?",[record_id($p['id'])]); return redirect('/small-business','Project closed.'); });
    $r->post('/small-business/project/{id}/entry/{entry}/delete',function ($p) { $id=record_id($p['id']); Db::run('DELETE FROM business_entries WHERE project_id=? AND id=?',[$id,record_id($p['entry'])]); return redirect('/small-business/project/'.$id,'Record removed. Project totals have been recalculated.'); });
};
